import{_ as e,o as i,c as n,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"2.2 Two Branches Bloom: Switching-Type and Balancing-Type Blocking","description":"","frontmatter":{"translationSource":{"title":"2.2 花开两朵：切换型阻塞与平衡型阻塞","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZDxRoi4GKekmLzgHNaf4fQ","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking"}]]},"headers":[],"relativePath":"2-2-two-branches-bloom-switching-type-and-balancing-type-blocking.md","filePath":"logistics/src/page-ZDxRoi4GKekmLzgHNaf4fQ.md"}'),a={name:"2-2-two-branches-bloom-switching-type-and-balancing-type-blocking.md"};function s(r,t,l,c,d,p){return i(),n("div",null,[...t[0]||(t[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="_2-2-花开两朵-切换型阻塞与平衡型阻塞" aria-hidden="true"></span><h1 id="_2-2-two-branches-bloom-switching-type-and-balancing-type-blocking" tabindex="-1">2.2 Two Branches Bloom: Switching-Type and Balancing-Type Blocking <a class="header-anchor" href="#_2-2-two-branches-bloom-switching-type-and-balancing-type-blocking" aria-label="Permalink to &quot;2\\.2 Two Branches Bloom: Switching-Type and Balancing-Type Blocking&quot;">​</a></h1><blockquote><p>Source page ID: <code>ZDxRoi4GKekmLzgHNaf4fQ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZDxRoi4GKekmLzgHNaf4fQ" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Two blocking schemes commonly used in production:</p><ol><li><p><span class="mark-red"><strong>Switching-type blocking</strong></span> (formerly type I): without manual intervention, blocking switches <span class="mark-purple"><strong>all</strong></span> material flow between routes, changing the product. Common uses: <strong>fully switching between products sharing inputs, retaining intermediates when output is surplus, etc.</strong></p></li><li><p><span class="mark-red"><strong>Balancing-type blocking</strong></span> (formerly type II): without manual intervention, blocking switches <span class="mark-purple"><strong>part</strong></span> of the flow between routes, reaching balance without changing products. Common uses: <strong>flow rates hard to obtain by splitting, adaptive balancing</strong>. Such lines generally run long-term.</p></li></ol><blockquote><p>These flow transfers describe time averages. Microscopically, all items use the other branch while blocking persists. Consumption then briefly clears blocking, restoring flow until it blocks again.</p></blockquote><p>The previous section&#39;s minimal example is switching-type blocking.</p><table tabindex="0"><thead><tr><th></th><th><span class="mark-red"><strong>Switching-type blocking</strong></span></th><th><span class="mark-red"><strong>Balancing-type blocking</strong></span></th></tr></thead><tbody><tr><td>Flow switched</td><td>All</td><td>Part</td></tr><tr><td>Main goal</td><td>Switch final products; retain intermediates/needed parts</td><td>Specific flow rates; adaptive balancing</td></tr><tr><td>Design focus</td><td><strong>What switches to what?</strong></td><td><strong>How does the initial state evolve toward balance?</strong></td></tr><tr><td>Typical use</td><td>Supply 30/m Ferrium Ore; first make Ferrium Parts at 30/m, then Ferrium Bottles at 15/m <u>once part storage fills</u></td><td>Supply 60/m Ferrium Ore: 13.75/m for Xircon, 46.25/m for Yazhen Syringe [C]</td></tr><tr><td>Stable state</td><td>No stable state: continuously make A, then continuously B</td><td>After stabilization, intended rates on long-term average</td></tr><tr><td>Priority design</td><td>Usually output priority (including stash priority with secondary output returning to depot)</td><td>Output priority or Splitters</td></tr><tr><td>Difficulty</td><td>Easy</td><td>Hard (flow and dynamic stability must be evaluated)</td></tr><tr><td>Blocking source</td><td>Usually <strong>stash</strong> or <strong>depot</strong></td><td>Usually <strong>machine buffer</strong> or <strong>blocking logistics structure</strong></td></tr><tr><td>Demands on two routes</td><td><strong>Secondary-route products not urgently needed short-term</strong></td><td><strong>Both should begin production as soon as possible</strong></td></tr></tbody></table><details><summary>AI summary diagram</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f3e492bba1fa0c43.q90-541e50d5e6be506e.webp" alt="22 Two Branches Bloom: Switching-Type and Balancing-Type Blocking"></p><div class="logistics-image-caption" data-source-block="M7euX5spAWVXU93BZkDVNZ"><p>Why does it feel like all that writing still can&#39;t beat AI?</p></div></details><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ea4a1c04901c8a60.q90-5d396658b6731317.webp" alt="22 Two Branches Bloom: Switching-Type and Balancing-Type Blocking"></p><div class="logistics-image-caption" data-source-block="mDH7AAYfk5AR4NQIHpoxX3"><p>A typical application of balancing-type blocking: from left to right, the first Protocol Stash provides priority output, and the second splits the flow equally.</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b2ec8f623a3ec66d.q90-2320cdd398d6847b.webp" alt="22 Two Branches Bloom: Switching-Type and Balancing-Type Blocking"></p><div class="logistics-image-caption" data-source-block="SUbkP1QmrOReCYsewvt9l3"><p>Limiting flow with a control port or a blocking splitter/converger structure also counts as balancing-type blocking (</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d8ed13533d840ed4.q90-28304f615fe1f868.webp" alt="22 Two Branches Bloom: Switching-Type and Balancing-Type Blocking"></p><div class="logistics-image-caption" data-source-block="6r3gut5DquedlXNC3yJgqD"><p>Another typical switching-type blocking design: once storage fills with Ferrium Parts produced at 30/min, it sends 30/min Ferrium back to the depot.</p></div><p>Balancing-type blocking keeps <strong>both routes consuming inputs and producing products at balanced rates</strong> after blocking forms. Sources usually lie mid-line: <strong>blocking structures connected to machines, insufficient machine speed causing buffer blocking,</strong> or <u><strong>insufficient other inputs in multi-input recipes causing buffer blocking</strong></u>. Without manual intervention, logistics structures and machine speeds cannot spontaneously adjust. The first two designs are therefore simpler and behave simply, but cannot control production by other material flows.</p><p>Both types yield reliable stable lines when production priorities are planned and <strong>priority</strong> layouts applied appropriately (see this section&#39;s appendix). For balancing-type blocking, <strong>splitting structures can replace priority</strong>, greatly simplifying design; see Section 2.5.</p><p><span class="mark-red">Both types can be combined.</span> In 言&#39;s automatic-switching line (<a href="/endfield-skydoc/some-simpler-adaptive-setups#source-block-ZJVOO6eIEMkLMbQvKmSE1N">Some Simpler Adaptive Setups</a>), an insufficient stock of Hetonite Parts first leads to production of Hetonite/Pyrrolite Parts and Heavy Xiranite, showing balancing-type blocking. Once Hetonite Part storage fills, all its Cuprium input shifts to Pyrrolite Parts, also showing switching-type blocking.</p><p><a href="/endfield-skydoc/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road">2.1 Hello World: Ferrium Ore at a Fork in the Road</a></p><p><a href="/endfield-skydoc/2-3-the-controlled-controlled-branch-and-the-unfree-free-branch">2.3 The Controlled Controlled Branch and the Unfree Free Branch (Considering Retirement)</a></p></div>',1)])])}const u=e(a,[["render",s]]);export{h as __pageData,u as default};
